package {{clientPackageName}};

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import net.minecraft.Util;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.components.Renderable;
import net.minecraft.client.gui.components.events.GuiEventListener;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.resources.sounds.SimpleSoundInstance;
import net.minecraft.network.chat.Component;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.util.FormattedCharSequence;

import org.lwjgl.glfw.GLFW;

/**
 * {{SCREEN_ID}} screen - generated by mcmodkit.
 * Theme, layout, buttons, animation and text come from the spec (ui.screens); edit the spec and
 * regenerate instead of editing here. Long bodies wrap and scroll; ESC returns to the parent screen.
 */
public class {{SCREEN_CLASS}} extends Screen {
	public static final int PANEL_WIDTH = {{SCREEN_WIDTH}};
	public static final int PANEL_HEIGHT = {{SCREEN_HEIGHT}};

	/** Preferred size from the spec; init() shrinks the panel to the window and re-centres everything. */
	private int panelWidth = PANEL_WIDTH;
	private int panelHeight = PANEL_HEIGHT;
	private static final String[] LINE_KEYS = {{LINE_KEYS_JAVA}};
	private static final int[] LINE_STYLES = {{LINE_STYLES_JAVA}};
	private static final int[] LINE_LINKS = {{LINE_LINKS_JAVA}};
	private static final String[] LINE_TARGET_KEYS = {{LINE_TARGET_KEYS_JAVA}};
	private static final String[] LINE_SECTION_KEYS = {{LINE_SECTION_KEYS_JAVA}};
	private static final String[] STEP_TEXT = {{STEP_TEXT_JAVA}};
	private static final String SEARCH_LANG_KEY = "{{SCREEN_SEARCH_KEY}}";
	private static final String SEARCH_CYCLE_LANG_KEY = "{{SCREEN_SEARCH_CYCLE_KEY}}";
	/** While the find bar is open its strip hides the top rows; jump landings drop below it. */
	private static final int SEARCH_BAR_CLEARANCE = 24;
	private static final int LINK_HOVER_COLOR = {{LINK_HOVER_COLOR}};
	private static final int LINK_PRESSED_COLOR = {{LINK_PRESSED_COLOR}};
	/** Spec key that closes this screen; -1 when no key opens it. */
	private static final int TOGGLE_KEY = {{SCREEN_KEY_CODE}};
	private static final int FLASH_MS = 600;
	private static final int EDGE_FADE_HEIGHT = 4;
	private static final int LINE_HEIGHT = 12;
	private static final int BODY_TOP = 42;
	private static final int BODY_SIDE = 16;
	private static final int FOOTER_HEIGHT = {{FOOTER_HEIGHT}};
	private static final int SCROLL_STEP = 18;
	private static final int SCROLL_ANIMATION_MS = 140;
	/** A jump across the whole document may take longer than a wheel notch, but never feels sluggish. */
	private static final int MAX_SCROLL_ANIMATION_MS = 280;
	private static final int ANIMATION_MS = 180;
	private static final int CLOSE_ANIMATION_MS = 120;
	private static final int PANEL_COLOR = {{PANEL_COLOR}};
	private static final int BORDER_COLOR = {{BORDER_COLOR}};
	private static final int ACCENT_COLOR = {{ACCENT_COLOR}};
	private static final int TITLE_COLOR = {{TITLE_COLOR}};
	private static final int BODY_COLOR = {{BODY_COLOR}};
	private static final int NOTE_COLOR = {{NOTE_COLOR}};
	private static final int WARN_COLOR = {{WARN_COLOR}};
	private static final boolean CENTER_TEXT = {{CENTER_TEXT}};
	private static final int ANIMATION_STYLE = {{ANIMATION_STYLE}};

	private final Screen parent;
	/** Logical line to reveal on the first init() (cross-screen deep link); consumed once. */
	private int initialLine = -1;
	private final List<FormattedCharSequence> rows = new ArrayList<>();
	private final List<Integer> rowWidths = new ArrayList<>();
	private final List<Integer> rowStyles = new ArrayList<>();
	private final List<Integer> rowIndents = new ArrayList<>();
	private final List<Boolean> rowStarts = new ArrayList<>();
	private final List<String> rowStepTexts = new ArrayList<>();
	private final List<Integer> rowLinks = new ArrayList<>();
	private final List<Component> lineTooltips = new ArrayList<>();
	private final List<Integer> lineStarts = new ArrayList<>();
	private final List<Integer> headingRows = new ArrayList<>();
	/** Logical line of each cached heading row, parallel to headingRows. */
	private final List<Integer> headingLines = new ArrayList<>();
	/** Heading text cached once per init so a hovered tick never allocates. */
	private final List<Component> headingTooltips = new ArrayList<>();
	private int hoveredHeading = -1;
	private boolean hasLinks;
	private int hoveredLink = -1;
	private int focusedLink = -1;

	/** Left-button link press awaiting release; the click opens only if the release lands on it. */
	private int pressedLink = -1;
	private EditBox searchBox;
	private final List<String> searchTexts = new ArrayList<>();
	private final List<Integer> searchMatches = new ArrayList<>();
	private int searchIndex = -1;
	private static String lastSearchQuery = "";
	private int[] searchHits;
	private boolean hoveredSearchCounter;
	private int hoveredSearchMark = -1;
	private int flashLine = -1;
	private long flashStartedAt;
	private int scrollOffset;
	private int scrollTarget;
	private int scrollStartOffset;
	/** Duration of the running animation; far jumps stretch it, wheel/page steps reset it to the base. */
	private int scrollDurationMs = SCROLL_ANIMATION_MS;
	private long scrollStartedAt;
	/** Last logical line scrolled into view; a fresh instance resumes there later in this session. */
	private static int rememberedLine = -1;
	/** False until the first init() so a fresh instance can restore rememberedLine. */
	private boolean laidOut;
	private boolean draggingScrollbar;
	private int scrollbarGrabOffset = -1;
	private boolean hoveringScrollbar;
	private long openedAt = -1L;
	private long closingAt = -1L;
	private boolean closeSwitched;
	private String displayTitle = "";
	private boolean titleTruncated;

	public {{SCREEN_CLASS}}() {
		this(null, -1);
	}

	public {{SCREEN_CLASS}}(Screen parent) {
		this(parent, -1);
	}

	public {{SCREEN_CLASS}}(Screen parent, int initialLine) {
		super(Component.translatable("{{SCREEN_TITLE_KEY}}"));
		this.parent = parent;
		this.initialLine = initialLine;
	}

	@Override
	protected void init() {
		// High GUI scales and small windows leave less room than the spec's preferred panel size.
		this.panelWidth = Math.min(PANEL_WIDTH, this.width - 16);
		this.panelHeight = Math.min(PANEL_HEIGHT, this.height - 16);
		this.displayTitle = this.trimmedTitle();
		// Text re-wraps when the window or GUI scale changes; keeping the raw scroll offset would
		// drop the reader into a different paragraph, so carry the logical line and its row offset.
		int anchorScroll = Math.max(0, this.currentScroll());
		int anchorLine = this.lineForScroll(anchorScroll);
		int anchorRow = 0;
		int anchorPixel = 0;
		if (anchorLine >= 0) {
			int topRow = Math.min(this.rows.size() - 1, anchorScroll / LINE_HEIGHT);
			anchorRow = topRow - this.lineStarts.get(anchorLine);
			anchorPixel = anchorScroll % LINE_HEIGHT;
		}
		int textWidth = this.panelWidth - BODY_SIDE * 2;
		this.rows.clear();
		this.rowWidths.clear();
		this.rowStyles.clear();
		this.rowIndents.clear();
		this.rowStarts.clear();
		this.rowStepTexts.clear();
		this.rowLinks.clear();
		this.lineTooltips.clear();
		this.lineStarts.clear();
		this.headingRows.clear();
		this.headingLines.clear();
		this.headingTooltips.clear();
		this.hoveredHeading = -1;
		this.hasLinks = false;
		this.hoveredLink = -1;
		this.focusedLink = -1;
		this.pressedLink = -1;
		this.flashLine = -1;
		// A resize rebuilds the layout under the bar; dropping it avoids a box pointing at stale rows.
		this.searchBox = null;
		this.searchIndex = -1;
		this.searchMatches.clear();
		this.searchTexts.clear();
		this.searchHits = null;
		this.draggingScrollbar = false;
		this.scrollbarGrabOffset = -1;
		int previousStyle = -1;
		for (int line = 0; line < LINE_KEYS.length; line++) {
			int style = LINE_STYLES[line];
			int indent = style == 2 || style == 3 || style == 4 || style == 5 ? 8 : 0;
			int target = LINE_LINKS[line];
			if (target >= 0) {
				this.hasLinks = true;
			}
			// Cached per init: a hovered frame must not allocate a Component.
			if (target < 0 || LINE_TARGET_KEYS[line].isEmpty()) {
				this.lineTooltips.add(null);
			} else if (LINE_SECTION_KEYS[line].isEmpty()) {
				this.lineTooltips.add(Component.translatable(LINE_TARGET_KEYS[line]));
			} else {
				// Deep link: name the landing section too, so a hover tooltip reads "Guide › What is generated".
				this.lineTooltips.add(Component.translatable(LINE_TARGET_KEYS[line]).append(" › ").append(Component.translatable(LINE_SECTION_KEYS[line])));
			}
			// One blank row separates a heading from the section above it; an opening heading stays flush.
			if (style == 1 && previousStyle != 1 && previousStyle != -1) {
				this.rows.add(FormattedCharSequence.EMPTY);
				this.rowWidths.add(0);
				this.rowStyles.add(0);
				this.rowIndents.add(0);
				this.rowStarts.add(false);
				this.rowLinks.add(-1);
				this.rowStepTexts.add("");
			}
			this.lineStarts.add(this.rows.size());
			boolean first = true;
			for (FormattedCharSequence row : this.font.split(Component.translatable(LINE_KEYS[line]), textWidth - indent)) {
				this.rows.add(row);
				this.rowWidths.add(this.font.width(row));
				this.rowStyles.add(style);
				this.rowIndents.add(indent);
				this.rowStarts.add(first);
				this.rowLinks.add(LINE_LINKS[line]);
				this.rowStepTexts.add(first ? STEP_TEXT[line] : "");
				if (first && style == 1) {
					this.headingRows.add(this.rows.size() - 1);
					this.headingLines.add(line);
					this.headingTooltips.add(Component.translatable(LINE_KEYS[line]));
				}
				first = false;
			}
			previousStyle = style;
		}
		if (anchorLine >= 0) {
			int line = Math.min(anchorLine, this.lineStarts.size() - 1);
			int lineEnd = line + 1 < this.lineStarts.size() ? this.lineStarts.get(line + 1) : this.rows.size();
			int row = Math.min(this.lineStarts.get(line) + anchorRow, Math.max(this.lineStarts.get(line), lineEnd - 1));
			this.scrollOffset = Math.min(row * LINE_HEIGHT + anchorPixel, this.maxScroll());
		} else if (!this.laidOut && this.initialLine < 0 && rememberedLine >= 0 && !this.lineStarts.isEmpty()) {
			// A fresh instance (closed and reopened) resumes the line this screen was last left at.
			this.scrollOffset = Math.min(this.lineStarts.get(Math.min(rememberedLine, this.lineStarts.size() - 1)) * LINE_HEIGHT, this.maxScroll());
		} else {
			this.scrollOffset = 0;
		}
		this.laidOut = true;
		this.scrollTarget = this.scrollOffset;
		this.scrollStartedAt = 0L;
		// Only the first init animates: resizing or returning from a child re-runs init() but must not replay the entrance.
		if (this.openedAt < 0L) {
			this.openedAt = Util.getMillis();
		}
		if (this.initialLine >= 0) {
			int line = this.initialLine;
			this.initialLine = -1;
			this.scrollToLine(line);
		}
		int left = (this.width - this.panelWidth) / 2;
		int top = (this.height - this.panelHeight) / 2;
{{SCREEN_BUTTON_WIDGETS}}
	}

	@Override
	public void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTick) {
		this.renderBackground(guiGraphics, mouseX, mouseY, partialTick);
		this.hoveringScrollbar = this.closingAt < 0L && this.scrollbarContains(mouseX, mouseY);
		float progress = this.animationProgress();
		this.hoveredLink = this.closingAt < 0L && this.hasLinks && !(this.searchBox != null && this.searchBarContains(mouseX, mouseY)) ? this.linkAt(mouseX, mouseY) : -1;
		this.hoveredHeading = this.closingAt < 0L ? this.headingAt(mouseX, mouseY) : -1;
		this.hoveredSearchCounter = this.closingAt < 0L && this.searchBox != null && this.searchCounterContains(mouseX, mouseY);
		this.hoveredSearchMark = this.closingAt < 0L ? this.searchMarkAt(mouseX, mouseY) : -1;
		int slide = this.currentSlide() + this.currentCloseSlide();
		int left = (this.width - this.panelWidth) / 2;
		int top = (this.height - this.panelHeight) / 2;
		guiGraphics.pose().pushPose();
		guiGraphics.pose().translate(0.0F, slide, 0.0F);
		this.drawPanel(guiGraphics, left, top);
		this.drawBody(guiGraphics, left, top, slide);
		for (GuiEventListener child : this.children()) {
			if (child instanceof Renderable) {
				((Renderable) child).render(guiGraphics, mouseX, mouseY, partialTick);
			}
		}
		guiGraphics.pose().popPose();
		if (ANIMATION_STYLE == 1 && progress < 1.0F) {
			guiGraphics.fill(0, 0, this.width, this.height, ((int) ((1.0F - progress) * 255.0F)) << 24);
		}
		if (this.hoveredSearchCounter) {
			// The counter doubles as the pointer's cycle button; hovering it spells out both keys.
			guiGraphics.renderTooltip(this.font, Component.translatable(SEARCH_CYCLE_LANG_KEY), mouseX, mouseY);
		} else if (this.hoveredSearchMark >= 0) {
			// A hit mark names its line on hover, mirroring the section ticks' tooltip.
			guiGraphics.renderTooltip(this.font, Component.translatable(LINE_KEYS[this.searchMatches.get(this.hoveredSearchMark)]), mouseX, mouseY);
		} else if (this.hoveredLink >= 0) {
			Component tooltip = this.lineTooltips.get(this.hoveredLink);
			if (tooltip != null) {
				guiGraphics.renderTooltip(this.font, tooltip, mouseX, mouseY);
			}
		} else if (this.focusedLink >= 0) {
			// Keyboard focus has no pointer: anchor the same cached tooltip under the focused row.
			Component tooltip = this.lineTooltips.get(this.focusedLink);
			if (tooltip != null) {
				int row = this.lineStarts.get(this.focusedLink);
				int x = left + BODY_SIDE;
				int y = top + BODY_TOP + this.currentSlide() + row * LINE_HEIGHT - this.currentScroll() + LINE_HEIGHT + 2;
				guiGraphics.renderTooltip(this.font, tooltip, x, y);
			}
		} else if (this.hoveredHeading >= 0) {
			// A tick names its section on hover; the text is cached per init.
			guiGraphics.renderTooltip(this.font, this.headingTooltips.get(this.hoveredHeading), mouseX, mouseY);
		}
		if (this.hoveredLink < 0 && this.focusedLink < 0 && this.hoveredHeading < 0 && this.hoveredSearchMark < 0 && this.titleTruncated && this.closingAt < 0L && this.titleContains(mouseX, mouseY)) {
			guiGraphics.renderTooltip(this.font, this.title, mouseX, mouseY);
		}
		if (this.closingAt >= 0L) {
			float close = this.closeProgress();
			guiGraphics.fill(0, 0, this.width, this.height, ((int) (close * 255.0F)) << 24);
			if (close >= 1.0F && !this.closeSwitched) {
				this.closeSwitched = true;
				this.minecraft.setScreen(this.parent);
			}
		}
	}

	private String trimmedTitle() {
		String full = this.title.getString();
		int maxWidth = this.panelWidth - BODY_SIDE * 2;
		this.titleTruncated = this.font.width(full) > maxWidth;
		if (!this.titleTruncated) {
			return full;
		}
		String ellipsis = "...";
		int available = maxWidth - this.font.width(ellipsis);
		if (available <= 0) {
			return ellipsis;
		}
		return this.font.plainSubstrByWidth(full, available) + ellipsis;
	}

	private boolean titleContains(double mouseX, double mouseY) {
		int slide = this.currentSlide() + this.currentCloseSlide();
		int left = (this.width - this.panelWidth) / 2;
		int top = (this.height - this.panelHeight) / 2 + slide;
		return mouseX >= left + BODY_SIDE && mouseX <= left + this.panelWidth - BODY_SIDE
				&& mouseY >= top + 8 && mouseY <= top + 31;
	}

	private void drawPanel(GuiGraphics guiGraphics, int left, int top) {
		// The world is dimmed but not flat; two translucent bands lift the panel without a texture.
		guiGraphics.fill(left - 3, top - 3, left + this.panelWidth + 3, top + this.panelHeight + 3, 0x18000000);
		guiGraphics.fill(left - 1, top - 1, left + this.panelWidth + 1, top + this.panelHeight + 1, 0x30000000);
		guiGraphics.fill(left, top, left + this.panelWidth, top + this.panelHeight, PANEL_COLOR);
		guiGraphics.fill(left, top, left + this.panelWidth, top + 1, BORDER_COLOR);
		guiGraphics.fill(left, top + this.panelHeight - 1, left + this.panelWidth, top + this.panelHeight, BORDER_COLOR);
		guiGraphics.fill(left, top, left + 1, top + this.panelHeight, BORDER_COLOR);
		guiGraphics.fill(left + this.panelWidth - 1, top, left + this.panelWidth, top + this.panelHeight, BORDER_COLOR);
		guiGraphics.fill(left + 1, top + 1, left + this.panelWidth - 1, top + 4, ACCENT_COLOR);
		guiGraphics.drawCenteredString(this.font, this.displayTitle, left + this.panelWidth / 2, top + 14, TITLE_COLOR);
		guiGraphics.fill(left + BODY_SIDE, top + 32, left + this.panelWidth - BODY_SIDE, top + 33, BORDER_COLOR);
		if (FOOTER_HEIGHT > 12) {
			guiGraphics.fill(left + BODY_SIDE, top + this.panelHeight - FOOTER_HEIGHT + 2, left + this.panelWidth - BODY_SIDE, top + this.panelHeight - FOOTER_HEIGHT + 3, BORDER_COLOR);
		}
	}

	private int rowColor(int style, int link) {
		if (link >= 0 || style == 1) {
			return ACCENT_COLOR;
		}
		return style == 3 ? NOTE_COLOR : style == 4 ? WARN_COLOR : BODY_COLOR;
	}

	private void drawBody(GuiGraphics guiGraphics, int left, int top, int slide) {
		int bodyTop = top + BODY_TOP;
		int viewport = this.viewportHeight();
		int maxScroll = this.maxScroll();
		int scroll = this.currentScroll();
		int first = Math.max(0, (scroll - this.bodyPad()) / LINE_HEIGHT);
		int last = Math.min(this.rows.size(), first + viewport / LINE_HEIGHT + 2);
		guiGraphics.enableScissor(left + 1, bodyTop + slide, left + this.panelWidth - 1, bodyTop + viewport + slide);
		for (int i = first; i < last; i++) {
			if (this.rowWidths.get(i) == 0) {
				continue;
			}
			int style = this.rowStyles.get(i);
			int indent = this.rowIndents.get(i);
			int x = CENTER_TEXT ? left + (this.panelWidth - this.rowWidths.get(i)) / 2 : left + BODY_SIDE + indent;
			int y = bodyTop + this.bodyPad() + i * LINE_HEIGHT - scroll;
			if (this.rowStarts.get(i) && style != 0) {
				if (style == 1) {
					guiGraphics.fill(x - 6, y, x - 4, y + 9, ACCENT_COLOR);
				} else if (style == 2) {
					guiGraphics.fill(x - 5, y + 4, x - 3, y + 6, ACCENT_COLOR);
				} else if (style == 5) {
					// Step numbers right-align in the marker gutter so two digits stay off the text.
					String step = this.rowStepTexts.get(i);
					guiGraphics.drawString(this.font, step, Math.max(left + 1, x - 3 - this.font.width(step)), y, ACCENT_COLOR, false);
				}
			}
			if (style == 3) {
				// Notes read as quoted secondary text: a dim rule marks every wrapped row.
				guiGraphics.fill(x - 6, y, x - 5, y + LINE_HEIGHT, NOTE_COLOR);
			}
			if (style == 4) {
				// A warning keeps the note layout but gets 2px of warm colour instead of the dim rule.
				guiGraphics.fill(x - 6, y, x - 4, y + LINE_HEIGHT, WARN_COLOR);
			}
			if (this.searchHits != null && i < this.searchHits.length && this.searchHits[i] > 0) {
				// Matches tint every row of the line; the one Enter would land on is stronger.
				int alpha = this.searchHits[i] - 1 == this.searchIndex ? 0x40 : 0x1C;
				guiGraphics.fill(x - 2, y - 1, x + this.rowWidths.get(i) + 2, y + LINE_HEIGHT - 1, (ACCENT_COLOR & 0x00FFFFFF) | (alpha << 24));
			}
			int flash = this.flashColor(i);
			if (flash != 0) {
				guiGraphics.fill(x - 2, y - 1, x + this.rowWidths.get(i) + 2, y + LINE_HEIGHT - 1, flash);
			}
			int link = this.rowLinks.get(i);
			boolean hovered = link >= 0 && link == this.hoveredLink;
			boolean pressed = hovered && link == this.pressedLink;
			boolean focused = link >= 0 && link == this.focusedLink;
			if (hovered) {
				guiGraphics.fill(x - 2, y - 1, x + this.rowWidths.get(i) + 2, y + LINE_HEIGHT - 1, pressed ? LINK_PRESSED_COLOR : LINK_HOVER_COLOR);
			}
			guiGraphics.drawString(this.font, this.rows.get(i), x, y, this.rowColor(style, link), false);
			if (hovered) {
				guiGraphics.fill(x, y + LINE_HEIGHT - (pressed ? 2 : 1), x + this.rowWidths.get(i), y + LINE_HEIGHT, ACCENT_COLOR);
			}
			if (focused) {
				guiGraphics.fill(x - 3, y - 1, x - 1, y + LINE_HEIGHT, ACCENT_COLOR);
				guiGraphics.fill(x - 1, y + LINE_HEIGHT - 1, x + this.rowWidths.get(i) + 1, y + LINE_HEIGHT, ACCENT_COLOR);
			}
		}
		// Edge fades use the panel colour so every theme gets a matching scroll affordance.
		int fadeHeight = Math.min(EDGE_FADE_HEIGHT, viewport / 2);
		if (scroll > 0) {
			for (int i = 0; i < fadeHeight; i++) {
				int alpha = 0xC0 - i * (0xC0 - 0x30) / Math.max(1, fadeHeight - 1);
				guiGraphics.fill(left + 1, bodyTop + slide + i, left + this.panelWidth - 1, bodyTop + slide + i + 1, (PANEL_COLOR & 0x00FFFFFF) | (alpha << 24));
			}
		}
		if (scroll < maxScroll) {
			for (int i = 0; i < fadeHeight; i++) {
				int alpha = 0x30 + i * (0xC0 - 0x30) / Math.max(1, fadeHeight - 1);
				int y = bodyTop + slide + viewport - fadeHeight + i;
				guiGraphics.fill(left + 1, y, left + this.panelWidth - 1, y + 1, (PANEL_COLOR & 0x00FFFFFF) | (alpha << 24));
			}
		}
		guiGraphics.disableScissor();
		if (this.searchBox != null) {
			// The find bar floats over the first rows on an opaque strip; the scrollbar map stays on top.
			int barTop = bodyTop - 8;
			int barBottom = bodyTop + 16;
			guiGraphics.fill(left + 3, barTop, left + this.panelWidth - 3, barBottom, (PANEL_COLOR & 0x00FFFFFF) | 0xFF000000);
			guiGraphics.fill(left + 3, barBottom, left + this.panelWidth - 3, barBottom + 1, BORDER_COLOR);
			String count = (this.searchIndex + 1) + "/" + this.searchMatches.size();
			guiGraphics.drawString(this.font, count, left + this.panelWidth - 6 - this.font.width(count), barTop + 8, this.searchMatches.isEmpty() ? NOTE_COLOR : ACCENT_COLOR, false);
		}
		if (maxScroll > 0) {
			int trackHeight = viewport;
			int thumbHeight = this.scrollbarThumbHeight();
			int thumbTop = this.scrollbarThumbTop(bodyTop);
			int trackWidth = this.hoveringScrollbar || this.draggingScrollbar ? 4 : 2;
			int x = left + this.panelWidth - 7;
			guiGraphics.fill(x, bodyTop, x + trackWidth, bodyTop + trackHeight, BORDER_COLOR);
			// Heading ticks make the track a section map; the section at the top of the viewport is bright.
			int currentHeading = this.currentHeading(scroll);
			int rowCount = Math.max(1, this.rows.size());
			for (int i = 0; i < this.headingRows.size(); i++) {
				int row = this.headingRows.get(i);
				int tickTop = bodyTop + row * trackHeight / rowCount;
				boolean current = row == currentHeading;
				boolean hovered = i == this.hoveredHeading;
				int tickWidth = hovered ? 7 : current ? 5 : 3;
				guiGraphics.fill(x - tickWidth, tickTop, x, tickTop + 1, hovered || current ? ACCENT_COLOR : ((ACCENT_COLOR & 0x00FFFFFF) | 0x80000000));
			}
			// Hit markers mirror the section ticks on the track's other edge, at a fixed anchor so a hover-widened track never shifts them; the cycle target or the hovered mark is full accent.
			int markLeft = x + 2;
			for (int i = 0; i < this.searchMatches.size(); i++) {
				int line = this.searchMatches.get(i);
				if (line >= this.lineStarts.size()) {
					continue;
				}
				int markTop = bodyTop + this.lineStarts.get(line) * trackHeight / rowCount;
				boolean target = i == this.searchIndex;
				boolean hovered = i == this.hoveredSearchMark;
				int markWidth = target || hovered ? 5 : 3;
				guiGraphics.fill(markLeft, markTop, markLeft + markWidth, markTop + 1, target || hovered ? ACCENT_COLOR : ((ACCENT_COLOR & 0x00FFFFFF) | 0x80000000));
			}
			guiGraphics.fill(x, thumbTop, x + trackWidth, thumbTop + thumbHeight, ACCENT_COLOR);
		}
	}

	private int currentScroll() {
		if (this.scrollStartedAt == 0L) {
			return this.scrollOffset;
		}
		long elapsed = Util.getMillis() - this.scrollStartedAt;
		if (elapsed >= this.scrollDurationMs) {
			this.scrollOffset = this.scrollTarget;
			this.scrollStartedAt = 0L;
			return this.scrollOffset;
		}
		float t = Math.max(0.0F, elapsed / (float) this.scrollDurationMs);
		float eased = 1.0F - (1.0F - t) * (1.0F - t);
		this.scrollOffset = this.scrollStartOffset + Math.round((this.scrollTarget - this.scrollStartOffset) * eased);
		return this.scrollOffset;
	}

	private void scrollTo(int target, boolean animate) {
		this.scrollTo(target, animate, SCROLL_ANIMATION_MS);
	}

	// One millisecond of extra travel per 12 px keeps far jumps readable without slowing nearby ones.
	private int scrollDurationFor(int target) {
		int clamped = Math.max(0, Math.min(this.maxScroll(), target));
		int distance = Math.abs(clamped - this.scrollTarget);
		return Math.min(MAX_SCROLL_ANIMATION_MS, SCROLL_ANIMATION_MS + distance / 12);
	}

	private void scrollTo(int target, boolean animate, int durationMs) {
		int clamped = Math.max(0, Math.min(this.maxScroll(), target));
		if (clamped == this.scrollTarget) {
			return;
		}
		this.scrollTarget = clamped;
		rememberedLine = this.lineForScroll(clamped);
		if (!animate) {
			this.scrollOffset = clamped;
			this.scrollStartedAt = 0L;
			return;
		}
		this.scrollStartOffset = this.scrollOffset;
		this.scrollDurationMs = Math.max(SCROLL_ANIMATION_MS, Math.min(MAX_SCROLL_ANIMATION_MS, durationMs));
		this.scrollStartedAt = Util.getMillis();
	}

	/** Logical line containing a scroll offset; -1 before the first layout. */
	private int lineForScroll(int scroll) {
		if (this.lineStarts.isEmpty() || this.rows.isEmpty()) {
			return -1;
		}
		int row = Math.min(this.rows.size() - 1, Math.max(0, scroll) / LINE_HEIGHT);
		int line = this.lineStarts.size() - 1;
		while (line > 0 && this.lineStarts.get(line) > row) {
			line--;
		}
		return line;
	}

	private int viewportHeight() {
		return this.panelHeight - BODY_TOP - FOOTER_HEIGHT;
	}

	// A page keeps one row of context so a page turn never cuts the sentence you were reading.
	private int pageStep() {
		return Math.max(LINE_HEIGHT, this.viewportHeight() - LINE_HEIGHT);
	}

	private int contentHeight() {
		return this.rows.size() * LINE_HEIGHT;
	}

	private int maxScroll() {
		return Math.max(0, this.contentHeight() + this.bodyPad() - this.viewportHeight());
	}

	/** The find bar's strip hides the top rows; while it is open the whole body shifts below it. */
	private int bodyPad() {
		return this.searchBox != null ? SEARCH_BAR_CLEARANCE : 0;
	}

	private float animationProgress() {
		if (ANIMATION_STYLE == 0) {
			return 1.0F;
		}
		long elapsed = Util.getMillis() - this.openedAt;
		if (elapsed >= ANIMATION_MS) {
			return 1.0F;
		}
		float t = Math.max(0.0F, elapsed / (float) ANIMATION_MS);
		return 1.0F - (1.0F - t) * (1.0F - t) * (1.0F - t);
	}

	private int currentSlide() {
		if (ANIMATION_STYLE != 2) {
			return 0;
		}
		return Math.round((1.0F - this.animationProgress()) * 10.0F);
	}

	private int currentCloseSlide() {
		if (ANIMATION_STYLE != 2 || this.closingAt < 0L) {
			return 0;
		}
		return Math.round(this.closeProgress() * 12.0F);
	}

	private float closeProgress() {
		if (this.closingAt < 0L) {
			return 0.0F;
		}
		long elapsed = Util.getMillis() - this.closingAt;
		if (elapsed >= CLOSE_ANIMATION_MS) {
			return 1.0F;
		}
		float t = Math.max(0.0F, elapsed / (float) CLOSE_ANIMATION_MS);
		return t * t;
	}

	@Override
	public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollY) {
		if (this.closingAt >= 0L) {
			return true;
		}
		if (this.maxScroll() > 0) {
			// A manual scroll ends keyboard link navigation: a focus ring or tooltip left off-screen
			// would still answer Enter for a link the player can no longer see.
			this.focusedLink = -1;
			this.pressedLink = -1;
			this.scrollTo(this.scrollTarget - (int) (scrollY * SCROLL_STEP), true);
			return true;
		}
		return super.mouseScrolled(mouseX, mouseY, scrollX, scrollY);
	}

	@Override
	public boolean mouseClicked(double mouseX, double mouseY, int button) {
		if (this.closingAt >= 0L) {
			return true;
		}
		// Any mouse press leaves keyboard link navigation; a completed link click re-focuses its row.
		this.focusedLink = -1;
		this.pressedLink = -1;
		if (this.searchBox != null && this.searchBarContains(mouseX, mouseY)) {
			if (button == 0 && !this.searchMatches.isEmpty() && this.searchCounterContains(mouseX, mouseY)) {
				// The counter is the pointer's cycle button; the rest of the strip stays the text field's.
				this.nextSearchMatch();
				return true;
			}
			if (button == 0 && this.jumpToSearchMark(mouseX, mouseY)) {
				// Marks drawn over the bar's rows keep their jump; the rest of the strip stays the text field's.
				return true;
			}
			// The bar overlays the first rows: its clicks must not reach the hidden links underneath.
			return super.mouseClicked(mouseX, mouseY, button);
		}
		if (button == 0) {
			int heading = this.headingAt(mouseX, mouseY);
			if (heading >= 0) {
				// A tick is a map pin: jump straight to that section with the anchor flash.
				this.scrollToLine(this.headingLines.get(heading));
				return true;
			}
		}
		if (button == 0 && this.jumpToSearchMark(mouseX, mouseY)) {
			// A mark is a find pin: jump to that hit and make it the cycle's current one.
			return true;
		}
		if (button == 0 && this.scrollbarContains(mouseX, mouseY)) {
			int thumbTop = this.scrollbarThumbTop();
			int thumbHeight = this.scrollbarThumbHeight();
			boolean onThumb = mouseY >= thumbTop && mouseY < thumbTop + thumbHeight;
			this.draggingScrollbar = true;
			// Grabbing the thumb keeps the pointer where it landed; a track click centres the thumb.
			this.scrollbarGrabOffset = onThumb ? (int) Math.round(mouseY) - thumbTop : thumbHeight / 2;
			if (onThumb) {
				this.scrollToMouse(mouseY);
			} else {
				// A track click glides to its spot like a section jump; dragging stays direct.
				int target = this.scrollbarScrollAt(mouseY, this.scrollbarGrabOffset);
				this.scrollTo(target, true, this.scrollDurationFor(target));
			}
			return true;
		}
		if (button == 0) {
			int line = this.linkAt(mouseX, mouseY);
			if (line >= 0) {
				// Like a vanilla button, a link commits on release so dragging off cancels the click.
				this.pressedLink = line;
				return true;
			}
		}
		return super.mouseClicked(mouseX, mouseY, button);
	}

	@Override
	public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
		if (this.closingAt >= 0L) {
			return true;
		}
		if (this.draggingScrollbar) {
			this.scrollToMouse(mouseY);
			return true;
		}
		return super.mouseDragged(mouseX, mouseY, button, dragX, dragY);
	}

	@Override
	public boolean mouseReleased(double mouseX, double mouseY, int button) {
		if (this.closingAt >= 0L) {
			this.draggingScrollbar = false;
			this.scrollbarGrabOffset = -1;
			this.pressedLink = -1;
			return true;
		}
		if (this.draggingScrollbar) {
			this.draggingScrollbar = false;
			this.scrollbarGrabOffset = -1;
			this.pressedLink = -1;
			return true;
		}
		if (button == 0 && this.pressedLink >= 0) {
			int pressed = this.pressedLink;
			this.pressedLink = -1;
			// Releasing off the row cancels the click, the same way a vanilla button does.
			if (this.linkAt(mouseX, mouseY) == pressed) {
				this.openLineLink(pressed);
			}
			return true;
		}
		return super.mouseReleased(mouseX, mouseY, button);
	}

	@Override
	public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
		if (this.closingAt >= 0L) {
			return true;
		}
		// Ctrl+F finds text inside this screen; the bar owns the keyboard while it holds focus.
		if (Screen.hasControlDown() && keyCode == GLFW.GLFW_KEY_F) {
			this.toggleSearch();
			return true;
		}
		if (this.searchBox != null && keyCode == GLFW.GLFW_KEY_ESCAPE) {
			this.closeSearch();
			return true;
		}
		if (this.searchBox != null && this.getFocused() == this.searchBox) {
			if (keyCode == GLFW.GLFW_KEY_ENTER || keyCode == GLFW.GLFW_KEY_KP_ENTER) {
				if (Screen.hasShiftDown()) {
					// Shift+Enter walks the hits backwards; both directions wrap around.
					this.prevSearchMatch();
				} else {
					this.nextSearchMatch();
				}
				return true;
			}
			// Arrows, backspace and typing all belong to the text field.
			return super.keyPressed(keyCode, scanCode, modifiers);
		}
		// Key mappings do not fire while a screen is open; this screen owns its own toggle key.
		if (TOGGLE_KEY >= 0 && keyCode == TOGGLE_KEY) {
			this.onClose();
			return true;
		}
		// Any key cancels a pending link press; only a press/release pair on the row opens it.
		this.pressedLink = -1;
		int maxScroll = this.maxScroll();
		if (maxScroll > 0) {
			// Ctrl + Up/Down steps through headings; the target line flashes like an anchor jump.
			if ((keyCode == GLFW.GLFW_KEY_UP || keyCode == GLFW.GLFW_KEY_DOWN) && Screen.hasControlDown() && !this.headingRows.isEmpty()) {
				this.focusedLink = -1;
				int row = this.headingStep(keyCode == GLFW.GLFW_KEY_DOWN);
				if (row >= 0) {
					this.scrollToLine(this.lineForScroll(row * LINE_HEIGHT));
				}
				return true;
			}
			// Page/Home/End are manual scrolls: like the wheel, they end keyboard link navigation.
			if (keyCode == GLFW.GLFW_KEY_PAGE_UP) {
				this.focusedLink = -1;
				this.scrollTo(this.scrollTarget - this.pageStep(), true);
				return true;
			}
			if (keyCode == GLFW.GLFW_KEY_PAGE_DOWN) {
				this.focusedLink = -1;
				this.scrollTo(this.scrollTarget + this.pageStep(), true);
				return true;
			}
			if (keyCode == GLFW.GLFW_KEY_HOME) {
				this.focusedLink = -1;
				this.scrollTo(0, true, this.scrollDurationFor(0));
				return true;
			}
			if (keyCode == GLFW.GLFW_KEY_END) {
				this.focusedLink = -1;
				this.scrollTo(maxScroll, true, this.scrollDurationFor(maxScroll));
				return true;
			}
		}
		if (keyCode == GLFW.GLFW_KEY_TAB) {
			this.focusedLink = -1;
		}
		if (this.hasLinks) {
			if (keyCode == GLFW.GLFW_KEY_DOWN) {
				this.focusLink(1);
				return true;
			}
			if (keyCode == GLFW.GLFW_KEY_UP) {
				this.focusLink(-1);
				return true;
			}
			if ((keyCode == GLFW.GLFW_KEY_ENTER || keyCode == GLFW.GLFW_KEY_KP_ENTER)
					&& this.focusedLink >= 0 && this.getFocused() == null) {
				this.openLineLink(this.focusedLink);
				return true;
			}
		}
		return super.keyPressed(keyCode, scanCode, modifiers);
	}

	private void toggleSearch() {
		if (this.searchBox != null) {
			this.closeSearch();
			return;
		}
		this.ensureSearchTexts();
		int left = (this.width - this.panelWidth) / 2;
		int top = (this.height - this.panelHeight) / 2;
		int boxWidth = Math.max(40, Math.min(140, this.panelWidth - BODY_SIDE * 2 - 34));
		this.searchBox = new EditBox(this.font, left + BODY_SIDE, top + BODY_TOP - 6, boxWidth, 20, Component.translatable(SEARCH_LANG_KEY));
		this.searchBox.setHint(Component.translatable(SEARCH_LANG_KEY));
		this.searchBox.setMaxLength(48);
		this.searchBox.setResponder(this::refreshSearch);
		// While the box exists the strip shifts the body down; keep the current view still.
		this.scrollTo(this.scrollOffset + this.bodyPad(), false);
		if (!lastSearchQuery.isEmpty()) {
			// Reopening the bar resumes the last search, like the browsers' find box.
			this.searchBox.setValue(lastSearchQuery);
		}
		this.addRenderableWidget(this.searchBox);
		this.setFocused(this.searchBox);
	}

	private void closeSearch() {
		if (this.searchBox == null) {
			return;
		}
		this.removeWidget(this.searchBox);
		this.searchBox = null;
		// Undo the search-time body shift now that the strip is gone.
		this.scrollTo(this.scrollOffset - SEARCH_BAR_CLEARANCE, false);
		this.searchIndex = -1;
		this.searchMatches.clear();
		this.searchHits = null;
		this.setFocused(null);
	}

	private void ensureSearchTexts() {
		if (!this.searchTexts.isEmpty()) {
			return;
		}
		for (String key : LINE_KEYS) {
			this.searchTexts.add(Component.translatable(key).getString().toLowerCase(Locale.ROOT));
		}
	}

	private void refreshSearch(String query) {
		lastSearchQuery = query;
		this.searchMatches.clear();
		this.searchIndex = -1;
		this.searchHits = null;
		String needle = query.trim().toLowerCase(Locale.ROOT);
		if (needle.isEmpty()) {
			return;
		}
		for (int line = 0; line < this.searchTexts.size(); line++) {
			if (this.searchTexts.get(line).contains(needle)) {
				this.searchMatches.add(line);
			}
		}
		if (!this.searchMatches.isEmpty()) {
			// Find-as-you-type starts at the first hit from the reader's position, wrapping to the top.
			int topLine = this.lineForScroll(this.scrollTarget);
			this.searchIndex = 0;
			for (int i = 0; i < this.searchMatches.size(); i++) {
				if (this.searchMatches.get(i) >= topLine) {
					this.searchIndex = i;
					break;
				}
			}
			this.scrollToLine(this.searchMatches.get(this.searchIndex));
		}
		this.searchHits = new int[this.rows.size()];
		for (int i = 0; i < this.searchMatches.size(); i++) {
			int line = this.searchMatches.get(i);
			int start = this.lineStarts.get(line);
			int end = line + 1 < this.lineStarts.size() ? this.lineStarts.get(line + 1) : this.rows.size();
			for (int row = start; row < end; row++) {
				this.searchHits[row] = i + 1;
			}
		}
	}

	private void nextSearchMatch() {
		if (this.searchMatches.isEmpty()) {
			return;
		}
		// Enter cycles through the hits; each stop re-flashes its line.
		this.searchIndex = (this.searchIndex + 1) % this.searchMatches.size();
		this.scrollToLine(this.searchMatches.get(this.searchIndex));
	}

	private void prevSearchMatch() {
		if (this.searchMatches.isEmpty()) {
			return;
		}
		// The + size - 1 keeps the modulo non-negative while stepping backwards.
		this.searchIndex = (this.searchIndex + this.searchMatches.size() - 1) % this.searchMatches.size();
		this.scrollToLine(this.searchMatches.get(this.searchIndex));
	}

	private boolean searchBarContains(double mouseX, double mouseY) {
		int slide = this.currentSlide() + this.currentCloseSlide();
		int left = (this.width - this.panelWidth) / 2 + 3;
		int top = (this.height - this.panelHeight) / 2 + slide + BODY_TOP - 8;
		return mouseX >= left && mouseX <= left + this.panelWidth - 6 && mouseY >= top && mouseY <= top + 25;
	}

	private boolean searchCounterContains(double mouseX, double mouseY) {
		int slide = this.currentSlide() + this.currentCloseSlide();
		int left = (this.width - this.panelWidth) / 2;
		int top = (this.height - this.panelHeight) / 2 + slide + BODY_TOP - 8;
		String count = (this.searchIndex + 1) + "/" + this.searchMatches.size();
		int textLeft = left + this.panelWidth - 6 - this.font.width(count);
		return mouseX >= textLeft - 2 && mouseX <= left + this.panelWidth - 3 && mouseY >= top && mouseY <= top + 24;
	}

	private void focusLink(int direction) {
		if (LINE_LINKS.length == 0) {
			return;
		}
		int line = this.focusedLink;
		for (int step = 0; step < LINE_LINKS.length; step++) {
			line += direction;
			if (line < 0) {
				line = LINE_LINKS.length - 1;
			} else if (line >= LINE_LINKS.length) {
				line = 0;
			}
			if (LINE_LINKS[line] >= 0) {
				this.setFocused(null);
				this.focusedLink = line;
				this.ensureLineVisible(line);
				return;
			}
		}
	}

	private void ensureLineVisible(int line) {
		if (line < 0 || line >= this.lineStarts.size()) {
			return;
		}
		int start = this.lineStarts.get(line) * LINE_HEIGHT;
		int endRow = line + 1 < this.lineStarts.size() ? this.lineStarts.get(line + 1) : this.rows.size();
		int end = endRow * LINE_HEIGHT;
		int scroll = this.scrollTarget;
		// Keep one text row of context around a keyboard-focused link; a link taller than the
		// viewport keeps its first row instead of hiding it under the top edge.
		int margin = LINE_HEIGHT;
		if (start < scroll) {
			this.scrollTo(Math.max(0, start - margin), true);
		} else if (end > scroll + this.viewportHeight()) {
			int target = Math.min(start, end + margin - this.viewportHeight());
			this.scrollTo(Math.max(0, target), true);
		}
	}

	private int flashColor(int row) {
		if (this.flashLine < 0 || this.flashLine >= this.lineStarts.size()) {
			return 0;
		}
		long elapsed = Util.getMillis() - this.flashStartedAt;
		if (elapsed >= FLASH_MS) {
			this.flashLine = -1;
			return 0;
		}
		int start = this.lineStarts.get(this.flashLine);
		int end = this.flashLine + 1 < this.lineStarts.size() ? this.lineStarts.get(this.flashLine + 1) : this.rows.size();
		if (row < start || row >= end) {
			return 0;
		}
		int alpha = (int) (0x55 * (1.0F - elapsed / (float) FLASH_MS));
		return (ACCENT_COLOR & 0x00FFFFFF) | (alpha << 24);
	}

	private int linkAt(double mouseX, double mouseY) {
		int left = (this.width - this.panelWidth) / 2;
		int top = (this.height - this.panelHeight) / 2 + BODY_TOP + this.currentSlide();
		int bottom = top + this.viewportHeight();
		if (mouseX < left + BODY_SIDE || mouseX >= left + this.panelWidth - BODY_SIDE) {
			return -1;
		}
		if (mouseY < top || mouseY >= bottom) {
			return -1;
		}
		int row = (this.currentScroll() + (int) mouseY - top - this.bodyPad()) / LINE_HEIGHT;
		if (row < 0 || row >= this.rowLinks.size()) {
			return -1;
		}
		// Truncation rounds clicks above the body back onto row 0; require the row's painted span.
		if (mouseY < top + this.bodyPad() + row * LINE_HEIGHT - this.currentScroll()) {
			return -1;
		}
		int link = this.rowLinks.get(row);
		if (link < 0) {
			return -1;
		}
		// The painted row is the hit target: empty panel space must not open a screen.
		int rowLeft = CENTER_TEXT
				? left + (this.panelWidth - this.rowWidths.get(row)) / 2
				: left + BODY_SIDE + this.rowIndents.get(row);
		return mouseX >= rowLeft - 2 && mouseX <= rowLeft + this.rowWidths.get(row) + 2 ? link : -1;
	}

	private void scrollToLine(int line) {
		if (line < 0 || line >= this.lineStarts.size()) {
			return;
		}
		this.flashLine = line;
		this.flashStartedAt = Util.getMillis();
		int target = this.lineStarts.get(line) * LINE_HEIGHT;
		this.scrollTo(target, true, this.scrollDurationFor(target));
	}

	private void openLineLink(int line) {
		this.minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK, 1.0F));
		this.focusedLink = line;
{{LINE_LINK_ACTIONS}}
	}

	private int scrollbarThumbHeight() {
		int trackHeight = this.viewportHeight();
		return Math.max(12, trackHeight * trackHeight / this.contentHeight());
	}

	private int scrollbarThumbTop(int bodyTop) {
		int trackHeight = this.viewportHeight();
		int thumbHeight = this.scrollbarThumbHeight();
		return bodyTop + (trackHeight - thumbHeight) * this.currentScroll() / Math.max(1, this.maxScroll());
	}

	// Tick hit box: the gutter left of the track, with a few pixels of vertical slack.
	private int headingAt(double mouseX, double mouseY) {
		if (this.maxScroll() <= 0) {
			return -1;
		}
		int x = (this.width - this.panelWidth) / 2 + this.panelWidth - 7;
		if (mouseX < x - 7 || mouseX > x) {
			return -1;
		}
		int bodyTop = (this.height - this.panelHeight) / 2 + BODY_TOP + this.currentSlide();
		int trackHeight = this.viewportHeight();
		int rowCount = Math.max(1, this.rows.size());
		for (int i = 0; i < this.headingRows.size(); i++) {
			int tickTop = bodyTop + this.headingRows.get(i) * trackHeight / rowCount;
			if (mouseY >= tickTop - 2 && mouseY <= tickTop + 2) {
				return i;
			}
		}
		return -1;
	}

	// Mark hit box: the gutter right of the track, with the same vertical slack as the ticks.
	private int searchMarkAt(double mouseX, double mouseY) {
		if (this.searchBox == null || this.searchMatches.isEmpty() || this.maxScroll() <= 0) {
			return -1;
		}
		int x = (this.width - this.panelWidth) / 2 + this.panelWidth - 7;
		if (mouseX < x + 2 || mouseX > x + 7) {
			return -1;
		}
		int bodyTop = (this.height - this.panelHeight) / 2 + BODY_TOP + this.currentSlide();
		int trackHeight = this.viewportHeight();
		int rowCount = Math.max(1, this.rows.size());
		for (int i = 0; i < this.searchMatches.size(); i++) {
			int line = this.searchMatches.get(i);
			if (line >= this.lineStarts.size()) {
				continue;
			}
			int markTop = bodyTop + this.lineStarts.get(line) * trackHeight / rowCount;
			if (mouseY >= markTop - 2 && mouseY <= markTop + 2) {
				return i;
			}
		}
		return -1;
	}

	private boolean jumpToSearchMark(double mouseX, double mouseY) {
		int mark = this.searchMarkAt(mouseX, mouseY);
		if (mark < 0) {
			return false;
		}
		// Landing on a mark makes it the cycle's current one, so Enter continues from there.
		this.searchIndex = mark;
		this.scrollToLine(this.searchMatches.get(mark));
		return true;
	}

	// Last heading that has scrolled to or above the viewport top; -1 while the preamble is on screen.
	private int currentHeading(int scroll) {
		int current = -1;
		for (int i = 0; i < this.headingRows.size(); i++) {
			int row = this.headingRows.get(i);
			if (row * LINE_HEIGHT > scroll) {
				break;
			}
			current = row;
		}
		return current;
	}

	// Heading row reached by one Ctrl+Up/Down step; -1 when already at an end.
	private int headingStep(boolean forward) {
		int current = this.currentHeading(this.scrollTarget);
		if (forward) {
			for (int i = 0; i < this.headingRows.size(); i++) {
				int row = this.headingRows.get(i);
				if (row > current) {
					return row;
				}
			}
			return -1;
		}
		int previous = -1;
		for (int i = 0; i < this.headingRows.size(); i++) {
			int row = this.headingRows.get(i);
			if (row >= current) {
				break;
			}
			previous = row;
		}
		return previous;
	}

	private int scrollbarThumbTop() {
		return this.scrollbarThumbTop((this.height - this.panelHeight) / 2 + BODY_TOP + this.currentSlide());
	}

	private boolean scrollbarContains(double mouseX, double mouseY) {
		if (this.maxScroll() <= 0) {
			return false;
		}
		int x = (this.width - this.panelWidth) / 2 + this.panelWidth - 8;
		int y = (this.height - this.panelHeight) / 2 + BODY_TOP + this.currentSlide();
		return mouseX >= x && mouseX <= x + 6 && mouseY >= y && mouseY <= y + this.viewportHeight();
	}

	// Where a pointer at mouseY would leave the thumb, given a grab offset inside it.
	private int scrollbarScrollAt(double mouseY, int grabOffset) {
		int maxScroll = this.maxScroll();
		if (maxScroll <= 0) {
			return 0;
		}
		int trackHeight = this.viewportHeight();
		int thumbHeight = this.scrollbarThumbHeight();
		int bodyTop = (this.height - this.panelHeight) / 2 + BODY_TOP + this.currentSlide();
		double grab = grabOffset >= 0 ? grabOffset : thumbHeight / 2.0D;
		double ratio = (mouseY - bodyTop - grab) / (trackHeight - thumbHeight);
		ratio = Math.max(0.0D, Math.min(1.0D, ratio));
		return (int) Math.round(ratio * maxScroll);
	}

	private void scrollToMouse(double mouseY) {
		this.scrollTo(this.scrollbarScrollAt(mouseY, this.scrollbarGrabOffset), false);
	}


	@Override
	public void onClose() {
		if (this.closingAt >= 0L) {
			return;
		}
		if (ANIMATION_STYLE == 0) {
			this.minecraft.setScreen(this.parent);
			return;
		}
		this.focusedLink = -1;
		this.closingAt = Util.getMillis();
	}
}

